# frozen_string_literal: true

require Rails.root.join("test/mailers/previews/ui_document_preview").to_s

# The committed files are generated by `rake command_tower:ui:email_fixtures`
# (rails_app/lib/tasks/ui_email_fixtures.rake); this keeps the generator reproducible.
RSpec.describe UiDocumentPreview, :aggregate_failures do
  it "previews every fixture" do
    expect(described_class.emails).to match_array(described_class.fixtures)
  end

  described_class.fixtures.each do |fixture|
    describe fixture do
      let(:output) { described_class.output(fixture) }
      let(:preview_mail) { described_class.new.public_send(fixture) }

      it "renders html equal to the committed fixture" do
        expect(File.read(described_class.path(fixture, "html"))).to eq(output.html), "#{fixture}.html is stale"
      end

      it "renders text equal to the committed fixture" do
        expect(File.read(described_class.path(fixture, "txt"))).to eq(output.text), "#{fixture}.txt is stale"
      end

      it "builds the preview mail without error" do
        expect(preview_mail.html_part.body.decoded).to eq(output.html)
        expect(preview_mail.text_part.body.decoded).to eq(output.text)
      end
    end
  end
end
